async function reuseDuration(row,feedback='history-status'){if(starting||savingRecord||activeSession||pendingSession||store.read().unsavedCount||['running','paused'].includes(timer.snapshot().state)){say('请先处理当前练习或未保存进度，再采用时长。',feedback);return}const minutes=reusableMinutes(row);if(minutes===null){say('此记录的计划时长不适用于整分钟安排，未改变设置。',feedback);return}const origin=viewRevision;$('duration').value=String(minutes);config();await persistPreferences({minutes});if(viewRevision!==origin||starting||activeSession||['running','paused'].includes(timer.snapshot().state))return;view('timer',true);openSettings($('open-settings'),true);say('已采用'+minutes+'分钟计划。其余安排沿用当前选择；请核对后手动开始。','arrangement-status')}
