$('export-history').onclick=async()=>{const origin=viewRevision,token=++exportGeneration;exportSnapshot=null;try{const fresh=await store.refresh();if(token!==exportGeneration||origin!==viewRevision||viewName!=='history')return;if(!fresh.refreshConfirmed||fresh.protectedData||fresh.conflict){say('未能确认可读的最新记录，未准备导出。请稍后重试。','history-status');return}exportPreview(store.exportData());$('export-dialog').showModal?.();$('cancel-export').focus?.()}catch{if(token===exportGeneration)say('暂时无法准备导出；原记录仍保留。','history-status')}};
