$('confirm-export').onclick=async()=>{const token=exportGeneration,snapshot=exportSnapshot;if(!snapshot)return;$('confirm-export').disabled=true;try{const fresh=await store.refresh();if(token!==exportGeneration||snapshot!==exportSnapshot)return;if(!fresh.refreshConfirmed||fresh.protectedData||fresh.conflict){$('export-summary').textContent='未能确认最新记录，未生成文件。请重试；原预览不是最新记录的证明。';return}const latest=store.exportData();if(exportSnapshotKey(latest)!==exportSnapshotKey(snapshot)){exportGeneration++;exportPreview(latest);$('export-summary').textContent='记录或设置已变化，请重新核对后再点下载。'+$('export-summary').textContent;return}exportFile=preparePracticeExport(snapshot,{Blob,URL});$('export-file-ready').hidden=false;$('export-copy-text').value=snapshot;$('export-file-status').textContent='备份是准备时的记录与设置快照；之后的变化不包含，本页已知变化会使其失效。共'+exportFile.bytes+'字节。点击下载，或展开复制备份文字；不会自动下载或上传。';$('export-download-link').textContent='下载这份备份';$('export-download-link').href=exportFile.url||'';$('export-download-link').download=exportFile.filename;$('export-download-link').hidden=!exportFile.url;$('confirm-export').hidden=true;$('cancel-export').textContent='关闭';if(exportFile.url)$('export-download-link').focus?.();else $('export-copy-text').focus?.()}catch{if(token===exportGeneration)$('export-summary').textContent='导出未完成；请确认浏览器允许下载。'}finally{if(token===exportGeneration)$('confirm-export').disabled=false}};

function stalePreparedExport(){if(!exportFile)return;exportGeneration++;exportPreview(store.exportData());$('export-summary').textContent='记录或设置已变化，原准备文件已失效。请重新核对并准备。'+$('export-summary').textContent;if($('export-dialog').open){$('confirm-export').focus?.();say('备份已失效，请重新准备。','export-file-status')}}
