function pendingUI(){$('resume-session').hidden=!pendingSession;if(pendingSession)$('resume-description').textContent=`${dateLabel(pendingSession.startedAt)}开始，已确认静坐${secondsLabel(pendingSession.elapsedSeconds)}，计划${secondsLabel(pendingSession.plannedSeconds)}。最后确认：${dateLabel(pendingSession.updatedAt)}；正常保存时约每15秒确认；写入失败或浏览器中断可能缺失更多。仅恢复最后确认进度，离开后不补记。${pendingSession.preparationRemainingMs>0?'尚余准备'+Math.ceil(pendingSession.preparationRemainingMs/1000)+'秒。':''}${pendingSession.legacyCuePlan||pendingSession.legacyPreparation?'旧进度缺少提示或准备信息，将保守静默恢复，不补记未知准备时间。':''}`}
$('restore-session').onclick=async()=>{if(!pendingSession||starting||savingRecord)return;starting=true;try{if(!await store.acquireActive()){say('另一页面正在练习；没有接管或修改上次进度。');return}await store.refresh();const p=store.read().activeSession||(!store.read().atomicCoordination?pendingSession:null);if(!p){pendingSession=null;pendingUI();store.releaseActive();say('此进度已由其他页面处理，请重新查看历史。');return}stopSound();timer.finish();$('duration').value=String(p.plannedSeconds/60);$('preparation').value=String(p.preparationSeconds);$('interval').value=String(p.intervalMinutes);cuePlan={...p.cuePlan};for(const key of ['startCue','intervalCue','endCue'])$(key.replace('Cue','-cue')).value=cuePlan[key];config();timer.restore({elapsedSeconds:p.elapsedSeconds,preparationRemainingMs:p.preparationRemainingMs});activeSession={...p,state:'paused',updatedAt:Math.max(p.startedAt,Date.now())};pendingSession=null;pendingUI();lastInterval=timer.snapshot().intervalsCompleted;cueReady=false;cueSchedule.reset();cueSchedule.observe(timer.snapshot(),{...cuePlan,audible:false});previousState='paused';await checkpoint(true);view('timer',true);$('timer-settings').open=false;say('已保留上次确认进度与提示安排，当前暂停；声音关闭。'+(p.legacyCuePlan||p.legacyPreparation?'旧进度缺少提示或准备信息，按静默／准备不补记恢复。':''))}catch{if(!activeSession)store.releaseActive();say('恢复未完成，未自动开始计时或播放。')}finally{starting=false;render()}};
$('discard-session').onclick=async()=>{if(!pendingSession||savingRecord)return;if(!await store.acquireActive()){say('另一页面正在使用该进度，未结束其练习。');return}try{await store.refresh();const p=store.read().activeSession||(!store.read().atomicCoordination?pendingSession:null);if(p)await store.addSession({id:p.id,startedAt:p.startedAt,endedAt:Math.max(p.startedAt,p.updatedAt),plannedSeconds:p.plannedSeconds,elapsedSeconds:p.elapsedSeconds,outcome:'interrupted',practiceId:p.practiceId,sound:p.sound});pendingSession=null;pendingUI();renderHistory();say(store.read().warning||'已结束上次进度，并按当前记录开关处理。')}catch{say('上次进度未成功处理，请保留本页并重试。')}finally{store.releaseActive()}};
$('retry-save-session').onclick=async()=>{try{await store.retryUnsaved();const d=storageFeedback();if(!activeSession){pendingSession=d.activeSession;pendingUI()}renderHistory();$('summary-saved').textContent=d.warning||(d.available?'本页待保存记录已保存。':'本页仍未持久保存。')}catch{say('重试未完成，记录仍在本页；可先导出。','history-status')}};
