function cancelPending(){cuePrepareGeneration++;previewGeneration++;startGeneration++;audioGeneration++;starting=false;$('start').disabled=false;$('end').textContent='结束本次'}
async function renderSilently(){const current=timer.snapshot();lastInterval=current.intervalsCompleted;cueSchedule.observe(current,{...cuePlan,audible:false});const was=previousState;previousState=current.state;if(current.state==='finished'&&was!=='finished')await finishRecord('completed',current);render();return current}
