function pauseForReading(){const state=timer.snapshot();if(!activeSession||!['running','paused'].includes(state.state))return Promise.resolve();if(state.state==='running')timer.pause();stopSound();render();say('已为阅读暂停计时；阅读时间不补记，回来后请手动继续。');return checkpoint(true)}
document.addEventListener('click',async event=>{if(event.defaultPrevented||event.button>0||event.metaKey||event.ctrlKey||event.shiftKey||event.altKey)return;const link=event.target?.closest?.('a');if(!link||link.hasAttribute('download')||link.hasAttribute('data-view'))return;let target;try{target=new URL(link.href,location.href)}catch{return}if(!['http:','https:'].includes(target.protocol))return;const here=new URL(location.href),samePage=target.origin===here.origin&&target.pathname===here.pathname&&target.search===here.search;if(samePage&&!target.hash)return;if(!activeSession)return;const flushing=pauseForReading();if(samePage||link.target==='_blank')return;event.preventDefault();const token=++pageNavigationGeneration;let timeout;await Promise.race([flushing,new Promise(resolve=>{timeout=setTimeout(resolve,2000)})]);clearTimeout(timeout);if(token===pageNavigationGeneration)location.assign(target.href)});
